-- ============================================================================
-- 07d4_zoneamento — SIGWEB SBN Maricá · Zoneamento (LC nº 400/2025) · PARTE 4 de 6
--
-- Polígonos do zoneamento: lote 3 de 4 (5 polígonos).
--
-- O SQL Editor do Supabase recusa scripts grandes; por isso o zoneamento vem em
-- 6 partes. RODE NA ORDEM: 07d1, 07d2, ... 07d6. Pode repetir qualquer
-- parte (os registros têm id fixo e são atualizados, não duplicados).
-- ============================================================================

set search_path = public, extensions;

insert into public.aux_zoneamento (id, zona, nome, sigla, tipo, ordem, geom) values
  (87, 'Macrozona Rural', 'Macrozona Rural', 'MR', 'macrozona', 10, ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Force2D(ST_CurveToLine(ST_SetSRID(''::geometry, 31983)))), 3))),
  (88, 'Macrozona Rural', 'Macrozona Rural', 'MR', 'macrozona', 10, ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Force2D(ST_CurveToLine(ST_SetSRID(''::geometry, 31983)))), 3))),
  (89, 'Macrozona Rural', 'Macrozona Rural', 'MR', 'macrozona', 10, ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Force2D(ST_CurveToLine(ST_SetSRID(''::geometry, 31983)))), 3))),
  (90, 'Macrozona Rural', 'Macrozona Rural', 'MR', 'macrozona', 10, ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Force2D(ST_CurveToLine(ST_SetSRID(''::geometry, 31983)))), 3))),
  (91, 'Macrozona de Urbanização Progressiva 1', 'Macrozona de Urbanização Progressiva 1', 'MUP 1', 'macrozona', 4, ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_Force2D(ST_CurveToLine(ST_SetSRID(''::geometry, 31983)))), 3)))
on conflict (id) do update set zona = excluded.zona, nome = excluded.nome, sigla = excluded.sigla,
  tipo = excluded.tipo, ordem = excluded.ordem, geom = excluded.geom, geom_web = null;

-- Esperado após esta parte (se as anteriores rodaram): 91 polígonos.
select 'parte 4 ok' as status, count(*) as poligonos_carregados from public.aux_zoneamento;
